-- Additive backoffice namespace. Existing marketing/contact tables are untouched.
-- No accounts, memberships, example customers, credentials or provider resources seeded.
begin;
create schema if not exists dg_bo_private;
revoke all on schema dg_bo_private from public, anon, authenticated;
create table public.dg_bo_workspaces(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 160),environment text not null check(environment in('development','staging','production')),created_at timestamptz not null default now());
create table public.dg_bo_organizations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.dg_bo_workspaces(id),name text not null check(length(name) between 1 and 160),billing_email text not null default '',country text not null default 'NL',billing_paused boolean not null default true check(billing_paused),revision bigint not null default 1,created_at timestamptz not null default now(),unique(workspace_id,id));
create index dg_bo_org_workspace_name on public.dg_bo_organizations(workspace_id,lower(name));
create table public.dg_bo_memberships(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),workspace_id uuid not null references public.dg_bo_workspaces(id),organization_id uuid,role text not null check(role in('admin','support','client')),permissions text[] not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),foreign key(workspace_id,organization_id) references public.dg_bo_organizations(workspace_id,id),check((role='client' and organization_id is not null) or (role<>'client' and organization_id is null)),unique(user_id,workspace_id));
create index dg_bo_membership_organization on public.dg_bo_memberships(workspace_id,organization_id);
create index dg_bo_membership_user_active on public.dg_bo_memberships(user_id) where active;
create table public.dg_bo_state(workspace_id uuid not null references public.dg_bo_workspaces(id),user_id uuid not null references auth.users(id),scope text not null,key text not null,value jsonb not null,revision bigint not null check(revision>0),updated_at timestamptz not null default now(),primary key(workspace_id,user_id,scope,key));
create table public.dg_bo_integrations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.dg_bo_workspaces(id),kind text not null,name text not null check(length(name) between 1 and 120),values jsonb not null,status text not null default 'draft' check(status in('draft','blocked','paused')),revision bigint not null default 1,last_test jsonb,test_history jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id));
create index dg_bo_integration_workspace on public.dg_bo_integrations(workspace_id,updated_at desc);
create table public.dg_bo_jobs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.dg_bo_workspaces(id),integration_id uuid references public.dg_bo_integrations(id),kind text not null,status text not null check(status in('blocked','completed')),metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index dg_bo_jobs_integration on public.dg_bo_jobs(integration_id);
create index dg_bo_jobs_workspace on public.dg_bo_jobs(workspace_id,created_at desc);
create table public.dg_bo_audit(id bigint generated always as identity primary key,workspace_id uuid not null references public.dg_bo_workspaces(id),actor_id uuid not null references auth.users(id),action text not null,resource_id text not null,outcome text not null,request_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index dg_bo_audit_workspace on public.dg_bo_audit(workspace_id,created_at desc);
create table public.dg_bo_idempotency(workspace_id uuid not null references public.dg_bo_workspaces(id),user_id uuid not null references auth.users(id),key text not null,fingerprint text not null,response jsonb not null,created_at timestamptz not null default now(),primary key(workspace_id,user_id,key));
create table public.dg_bo_support_tickets(id text primary key default ('DG-'||upper(replace(gen_random_uuid()::text,'-',''))),workspace_id uuid not null references public.dg_bo_workspaces(id),organization_id uuid not null,subject text not null check(length(subject) between 1 and 160),service text not null,category text not null,priority text not null check(priority in('normal','high','urgent')),status text not null check(status in('new','open','waiting','resolved')),assignee text not null default 'Nog niet toegewezen',revision bigint not null default 1,public_revision bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),public_updated_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id,organization_id) references public.dg_bo_organizations(workspace_id,id));
create index dg_bo_ticket_org on public.dg_bo_support_tickets(workspace_id,organization_id,public_updated_at desc);
create index dg_bo_ticket_staff on public.dg_bo_support_tickets(workspace_id,updated_at desc);
create table public.dg_bo_support_messages(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,ticket_id text not null,visibility text not null check(visibility in('public','internal')),author text not null,body text not null check(length(body) between 1 and 8000),type text not null default 'message' check(type in('message','system')),event_order bigint generated always as identity,created_at timestamptz not null default now(),foreign key(workspace_id,ticket_id) references public.dg_bo_support_tickets(workspace_id,id));
create index dg_bo_message_thread on public.dg_bo_support_messages(workspace_id,ticket_id,visibility,event_order);
create table public.dg_bo_support_drafts(workspace_id uuid not null references public.dg_bo_workspaces(id),user_id uuid not null references auth.users(id),scope text not null,key text not null,value jsonb not null,revision bigint not null,updated_at timestamptz not null default now(),primary key(workspace_id,user_id,scope,key));
create table public.dg_bo_customer_sources(workspace_id uuid not null,source_type text not null,customer_reference text not null,organization_id uuid not null,metadata jsonb not null,primary key(workspace_id,source_type,customer_reference),foreign key(workspace_id,organization_id) references public.dg_bo_organizations(workspace_id,id));
create index dg_bo_source_org on public.dg_bo_customer_sources(workspace_id,organization_id);
create table public.dg_bo_import_plans(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.dg_bo_workspaces(id),user_id uuid not null references auth.users(id),integration_id uuid not null references public.dg_bo_integrations(id),integration_revision bigint not null,configuration_digest text not null,registry_revision bigint not null,digest text not null,plan jsonb not null,expires_at timestamptz not null,created_at timestamptz not null default now());
create index dg_bo_plan_actor on public.dg_bo_import_plans(workspace_id,user_id,integration_id);
create table public.dg_bo_import_receipts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.dg_bo_workspaces(id),source_type text not null,batch_reference text not null,line_reference text not null,configuration_digest text not null,receipt jsonb not null,created_at timestamptz not null default now(),unique(workspace_id,source_type,batch_reference,line_reference));
-- Tables are exclusively reachable through security-definer RPCs with current context.
do $$ declare r record;begin for r in select tablename from pg_tables where schemaname='public' and left(tablename,6)='dg_bo_' loop execute format('alter table public.%I enable row level security',r.tablename);execute format('revoke all on table public.%I from public,anon,authenticated',r.tablename);end loop;end $$;
revoke all on sequence public.dg_bo_audit_id_seq,public.dg_bo_support_messages_event_order_seq from public,anon,authenticated;
create function dg_bo_private.fail(p_status integer,p_code text,p_message text,p_details jsonb default '{}') returns void language plpgsql set search_path='' as $$ begin raise exception using errcode='P0001',message=jsonb_build_object('status',p_status,'value',jsonb_build_object('code',p_code,'message',p_message)||p_details)::text;end $$;
create function dg_bo_private.assert_clean(v jsonb,depth integer default 0) returns void language plpgsql set search_path='' as $$ declare k text;x jsonb;t text;begin
 if depth>24 or octet_length(v::text)>1000000 then perform dg_bo_private.fail(422,'INVALID_DATA','De gegevens zijn te groot of te diep genest.');end if;
 if jsonb_typeof(v)='string' then t=v#>>'{}';if t ~* '(-----BEGIN [A-Z ]*PRIVATE KEY-----|github_pat_[A-Za-z0-9_]{16,}|gh[pousr]_[A-Za-z0-9_]{16,}|sb_secret_[A-Za-z0-9_-]{8,}|sk-(proj-)?[A-Za-z0-9_-]{16,}|(https?|postgres(ql)?|ssh)://[^ /@:]+:[^ /@]+@|eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}|(password|passwd|api[_ -]?key|access[_ -]?token|secret[_ -]?key|service[_ -]?role)[[:space:]]*[:=][[:space:]]*[^[:space:]]+)' then perform dg_bo_private.fail(422,'SECRET_NOT_ALLOWED','Bewaar uitsluitend metadata, geen geheime waarden.');end if;
 elsif jsonb_typeof(v)='object' then for k,x in select * from jsonb_each(v) loop if k in('__proto__','constructor','prototype') then perform dg_bo_private.fail(422,'INVALID_FIELD','Ongeldig gegevensveld.');end if;if k ~* '((password|passwd|passphrase|access[_-]?token|refresh[_-]?token|api[_-]?key|private[_-]?key|secret[_-]?value|credentials?|service[_-]?role|authorization)$|^(token|secret)$)' and x not in('null'::jsonb,'false'::jsonb,'""'::jsonb) then perform dg_bo_private.fail(422,'SECRET_NOT_ALLOWED','Geheime velden zijn niet toegestaan.');end if;perform dg_bo_private.assert_clean(x,depth+1);end loop;
 elsif jsonb_typeof(v)='array' then for x in select * from jsonb_array_elements(v) loop perform dg_bo_private.assert_clean(x,depth+1);end loop;end if;end $$;
create function dg_bo_private.context() returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();j jsonb:=auth.jwt();m public.dg_bo_memberships;begin
 if u is null or j->>'aal' is distinct from 'aal2' or coalesce((j->>'exp')::numeric,0)<=extract(epoch from now()) then perform dg_bo_private.fail(401,'MFA_REQUIRED','Meld je aan met tweestapsverificatie.');end if;
 if not exists(select 1 from auth.users x where x.id=u and not coalesce(x.is_anonymous,false) and x.deleted_at is null and x.email_confirmed_at is not null and (x.banned_until is null or x.banned_until<=now())) or not exists(select 1 from auth.sessions s join auth.mfa_factors f on f.id=s.factor_id and f.user_id=s.user_id and f.status::text='verified' and f.factor_type::text in('totp','phone','webauthn') where s.id=(j->>'session_id')::uuid and s.user_id=u and s.aal::text='aal2' and (s.not_after is null or s.not_after>now())) then perform dg_bo_private.fail(401,'SESSION_REVOKED','Deze aanmeldsessie is niet meer geldig.');end if;
 if (select count(*) from public.dg_bo_memberships x where x.user_id=u and x.active)<>1 then perform dg_bo_private.fail(403,'MEMBERSHIP_REQUIRED','Een bevoegde beheerder moet precies één actief lidmaatschap toewijzen.');end if;
 select * into m from public.dg_bo_memberships x where x.user_id=u and x.active;
 return jsonb_build_object('id',u,'role',m.role,'workspaceId',m.workspace_id,'organizationId',m.organization_id,'permissions',to_jsonb(m.permissions));
 exception when invalid_text_representation or numeric_value_out_of_range then perform dg_bo_private.fail(401,'AUTH_REQUIRED','Meld je opnieuw aan.');return null;end $$;
create function public.dg_bo_context() returns jsonb language sql security definer set search_path='' as $$select dg_bo_private.context()$$;
revoke all on function public.dg_bo_context() from public,anon;grant execute on function public.dg_bo_context() to authenticated;
create function dg_bo_private.require_permission(a jsonb,p text,staff boolean default false) returns void language plpgsql set search_path='' as $$begin if not coalesce((a->'permissions')?p,false) or (staff and a->>'role' not in('admin','support')) then perform dg_bo_private.fail(403,'FORBIDDEN','Deze sessie mag deze handeling niet uitvoeren.');end if;end $$;
create function dg_bo_private.audit(a jsonb,action text,resource text,outcome text,request_id text,metadata jsonb default '{}') returns void language sql set search_path='' as $$ insert into public.dg_bo_audit(workspace_id,actor_id,action,resource_id,outcome,request_id,metadata) values((a->>'workspaceId')::uuid,(a->>'id')::uuid,action,resource,outcome,left(request_id,128),metadata) $$;
create function dg_bo_private.immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'append-only backoffice event';end$$;
create trigger dg_bo_audit_immutable before update or delete on public.dg_bo_audit for each row execute function dg_bo_private.immutable();
create trigger dg_bo_message_immutable before update or delete on public.dg_bo_support_messages for each row execute function dg_bo_private.immutable();

