:true,"maxLength":1000,"options":["INBOX"]}]},{"fields":[{"name":"brandName","type":"text","required":true,"maxLength":1000},{"name":"senderName","type":"text","required":true,"maxLength":80},{"name":"sender","type":"email","required":true,"maxLength":1000},{"name":"replyTo","type":"email","required":true,"maxLength":1000},{"name":"brandColor","type":"text","required":true,"maxLength":1000,"pattern":"#[0-9a-fA-F]{6}"},{"name":"signature","type":"textarea","required":true,"maxLength":320}]},{"fields":[{"name":"memberReference","type":"select","required":true,"maxLength":1000,"options":["fixture-member-danny","fixture-member-support"]},{"name":"accessPolicy","type":"select","required":true,"maxLength":1000,"options":["read-only","reply-note","coordinate"]}]},{"fields":[]},{"fields":[{"name":"importPolicy","type":"select","required":true,"maxLength":1000,"options":["from-now","last-7-days","last-30-days"]},{"name":"mailboxPolicy","type":"select","required":true,"maxLength":1000,"options":["read-only"]}]},{"fields":[]}]},"customers-import":{"steps":[{"fields":[{"name":"configurationName","type":"text","required":true,"maxLength":80},{"name":"sourceType","type":"select","required":true,"maxLength":1000,"options":["fixture-csv","fixture-20i","manual"]},{"name":"batchReference","type":"text","required":true,"maxLength":1000}]},{"fields":[{"name":"customerReference","type":"text","required":true,"maxLength":1000},{"name":"organizationName","type":"text","required":true,"maxLength":1000},{"name":"billingEmail","type":"email","required":true,"maxLength":1000},{"name":"country","type":"select","required":true,"maxLength":1000,"options":["NL","BE","DE"]},{"name":"resourceReference","type":"select","required":true,"maxLength":1000,"options":["unlinked","fixture-pkg-001"]}]},{"fields":[{"name":"productVersion","type":"text","required":true,"maxLength":1000},{"name":"paidThrough","type":"date","required":true,"maxLength":1000},{"name":"nextInvoiceDate","type":"date","required":true,"maxLength":1000},{"name":"billingPolicy","type":"select","required":true,"maxLength":1000,"options":["paused-review"]},{"name":"owner","type":"text","required":true,"maxLength":1000}]},{"fields":[]},{"fields":[]}]},"mollie":{"steps":[{"fields":[{"name":"configurationName","type":"text","required":true,"maxLength":80},{"name":"paymentMode","type":"select","required":true,"maxLength":1000,"options":["test"]},{"name":"accountReference","type":"text","required":true,"maxLength":1000}]},{"fields":[{"name":"webhookProfile","type":"select","required":true,"maxLength":1000,"options":["fixture-payments"]},{"name":"paymentMethods","type":"select","required":true,"maxLength":1000,"options":["fixture-checkout"]}]},{"fields":[{"name":"invoiceReference","type":"text","required":true,"maxLength":1000},{"name":"amountCents","type":"number","required":true,"maxLength":1000,"min":1,"max":100000},{"name":"currency","type":"select","required":true,"maxLength":1000,"options":["EUR"]},{"name":"recurringPolicy","type":"select","required":true,"maxLength":1000,"options":["disabled"]}]},{"fields":[]},{"fields":[]}]},"system-mail":{"steps":[{"fields":[{"name":"configurationName","type":"text","required":true,"maxLength":80},{"name":"messagePurpose","type":"select","required":true,"maxLength":1000,"options":["service-notices","invoices","auth-otp","support-notifications"]},{"name":"providerProfile","type":"select","required":true,"maxLength":1000,"options":["fixture-system-mail"]}]},{"fields":[{"name":"senderName","type":"text","required":true,"maxLength":1000},{"name":"sender","type":"email","required":true,"maxLength":1000},{"name":"replyTo","type":"email","required":true,"maxLength":1000},{"name":"testRecipient","type":"email","required":true,"maxLength":1000}]},{"fields":[{"name":"templateVersion","type":"text","required":true,"maxLength":1000},{"name":"subject","type":"text","required":true,"maxLength":1000},{"name":"templateText","type":"textarea","required":true,"maxLength":1000}]},{"fields":[]},{"fields":[]}]},"webmail":{"steps":[{"fields":[{"name":"configurationName","type":"text","required":true,"maxLength":80},{"name":"endpoint","type":"url","required":true,"maxLength":1000},{"name":"publicHostname","type":"text","required":true,"maxLength":1000}]},{"fields":[{"name":"brandName","type":"text","required":true,"maxLength":1000},{"name":"brandColor","type":"text","required":true,"maxLength":1000,"pattern":"#[0-9a-fA-F]{6}"},{"name":"loginMethod","type":"select","required":true,"maxLength":1000,"options":["mailbox","sso-review"]},{"name":"assetReference","type":"select","required":true,"maxLength":1000,"options":["dg-brand"]}]},{"fields":[{"name":"owner","type":"text","required":true,"maxLength":1000},{"name":"operatorNote","type":"textarea","required":false,"maxLength":1000}]},{"fields":[]},{"fields":[]}]},"staff":{"steps":[{"fields":[{"name":"configurationName","type":"text","required":true,"maxLength":80},{"name":"inviteeEmail","type":"email","required":true,"maxLength":1000},{"name":"roleTemplate","type":"select","required":true,"maxLength":1000,"options":["projectinbox-agent","projectinbox-coordinator","read-only"]}]},{"fields":[{"name":"projectRef","type":"select","required":true,"maxLength":1000,"options":["fixture-project-fieldgrid","fixture-project-dartflow"]},{"name":"inboxReference","type":"select","required":true,"maxLength":1000,"options":["fixture-inbox-support"]},{"name":"accessPolicy","type":"select","required":true,"maxLength":1000,"options":["read-reply-note","read-assign","read-only"]}]},{"fields":[{"name":"invitationExpiry","type":"select","required":true,"maxLength":1000,"options":["48h","24h"]},{"name":"mfaPolicy","type":"select","required":true,"maxLength":1000,"options":["required"]},{"name":"owner","type":"text","required":true,"maxLength":1000}]},{"fields":[]},{"fields":[]}]},"wizard:deploy":{"steps":[{"fields":[{"name":"projectName","type":"text","required":true,"maxLength":80},{"name":"projectCode","type":"text","required":true,"maxLength":32,"pattern":"[A-Z][A-Z0-9_]{1,31}"},{"name":"repository","type":"text","required":true,"maxLength":160,"pattern":"[A-Za-z0-9_.\\-]+/[A-Za-z0-9_.\\-]+"},{"name":"branch","type":"text","required":true,"maxLength":100},{"name":"owner","type":"text","required":true,"maxLength":160},{"name":"devVps","type":"text","required":true,"maxLength":160},{"name":"scope","type":"select","required":true,"maxLength":300,"options":["prepare","staging","production"]},{"name":"hostKind","type":"select","required":true,"maxLength":300,"options":["existing","new"]},{"name":"scopeNote","type":"textarea","required":false,"maxLength":600}]},{"fields":[{"name":"stagingHost","type":"text","required":true,"maxLength":160},{"name":"productionHost","type":"text","required":true,"maxLength":160},{"name":"stagingOrigin","type":"url","required":true,"maxLength":240},{"name":"productionOrigin","type":"url","required":true,"maxLength":240},{"name":"stagingPort","type":"number","required":false,"maxLength":160,"min":1,"max":65535},{"name":"productionPort","type":"number","required":false,"maxLength":160,"min":1,"max":65535},{"name":"stagingConfig","type":"text","required":false,"maxLength":160},{"name":"productionConfig","type":"text","required":false,"maxLength":160},{"name":"stagingRunner","type":"text","required":false,"maxLength":160},{"name":"productionRunner","type":"text","required":false,"maxLength":160}]},{"fields":[{"name":"stagingProjectRef","type":"text","required":true,"maxLength":100},{"name":"productionProjectRef","type":"text","required":true,"maxLength":100},{"name":"stagingSupabase","type":"url","required":true,"maxLength":240},{"name":"productionSupabase","type":"url","required":true,"maxLength":240},{"name":"authMode","type":"select","required":true,"maxLength":300,"options":["otp","google","both","other"]},{"name":"callback","type":"text","required":false,"maxLength":120},{"name":"authReference","type":"textarea","required":false,"maxLength":500}]},{"fields":[{"name":"varsConfirmed","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"toolchain","type":"text","required":false,"maxLength":160},{"name":"hostEvidence","type":"text","required":false,"maxLength":160},{"name":"releaseContract","type":"textarea","required":false,"maxLength":600},{"name":"hostConfirmed","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"sourceSha","type":"text","required":false,"maxLength":40,"pattern":"[0-9a-fA-F]{40}"},{"name":"ciEvidence","type":"text","required":false,"maxLength":240},{"name":"acceptedSha","type":"text","required":false,"maxLength":40,"pattern":"[0-9a-fA-F]{40}"},{"name":"acceptanceEvidence","type":"text","required":false,"maxLength":240},{"name":"ciGreen","type":"checkbox","required":false,"maxLength":300},{"name":"stagingHealthy","type":"checkbox","required":false,"maxLength":300},{"name":"stagingAccepted","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"approvalEvidence","type":"text","required":false,"maxLength":240},{"name":"productionApproved","type":"checkbox","required":false,"maxLength":300},{"name":"restoreReference","type":"text","required":false,"maxLength":240},{"name":"restoreReady","type":"checkbox","required":false,"maxLength":300}]},{"fields":[]}]},"wizard:hardening":{"steps":[{"fields":[{"name":"hostName","type":"text","required":true,"maxLength":160,"pattern":"[A-Za-z0-9][A-Za-z0-9.-]{0,62}"},{"name":"providerId","type":"text","required":true,"maxLength":160},{"name":"region","type":"text","required":false,"maxLength":160},{"name":"owner","type":"text","required":false,"maxLength":160},{"name":"profile","type":"select","required":true,"maxLength":300,"options":["new","existing"]},{"name":"role","type":"select","required":true,"maxLength":300,"options":["Web","Beheer","Build","Gemengd"]},{"name":"environment","type":"select","required":true,"maxLength":300,"options":["Development","Staging","Productie","Beheer","Gemengd"]},{"name":"image","type":"text","required":true,"maxLength":160},{"name":"architecture","type":"select","required":true,"maxLength":300,"options":["x86_64","aarch64","Onbekend"]},{"name":"publicIpv4","type":"text","required":false,"maxLength":160},{"name":"publicIpv6","type":"text","required":false,"maxLength":160},{"name":"capacity","type":"text","required":false,"maxLength":160},{"name":"inventoryVerified","type":"checkbox","required":false,"maxLength":300},{"name":"consoleVerified","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"adminUser","type":"text","required":false,"maxLength":160},{"name":"keyReference","type":"text","required":false,"maxLength":160},{"name":"hostKeyVerified","type":"checkbox","required":false,"maxLength":300},{"name":"ubuntuVerified","type":"checkbox","required":false,"maxLength":300},{"name":"adminVerified","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"tailName","type":"text","required":false,"maxLength":160},{"name":"tailTag","type":"text","required":false,"maxLength":160},{"name":"grantRef","type":"text","required":false,"maxLength":160},{"name":"tailLoginVerified","type":"checkbox","required":false,"maxLength":300},{"name":"tailPolicyVerified","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"sshConfigVerified","type":"checkbox","required":false,"maxLength":300},{"name":"tailAfterReloadVerified","type":"checkbox","required":false,"maxLength":300},{"name":"dualFirewallVerified","type":"checkbox","required":false,"maxLength":300},{"name":"publicSshClosed","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"toolchain","type":"text","required":false,"maxLength":160},{"name":"maintenanceWindow","type":"text","required":false,"maxLength":160},{"name":"baselineRef","type":"text","required":false,"maxLength":160},{"name":"maintenanceVerified","type":"checkbox","required":false,"maxLength":300},{"name":"runtimeVerified","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"siteRef","type":"text","required":false,"maxLength":160},{"name":"runnerEvidence","type":"text","required":false,"maxLength":160},{"name":"isolationVerified","type":"checkbox","required":false,"maxLength":300},{"name":"runnerVerified","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"recoveryPolicy","type":"text","required":false,"maxLength":160},{"name":"acceptanceEvidence","type":"textarea","required":false,"maxLength":1200},{"name":"readinessVerified","type":"checkbox","required":false,"maxLength":300},{"name":"restoreVerified","type":"checkbox","required":false,"maxLength":300},{"name":"rebootVerified","type":"checkbox","required":false,"maxLength":300},{"name":"monitoringVerified","type":"checkbox","required":false,"maxLength":300}]},{"fields":[{"name":"registerInDg","type":"checkbox","required":false,"maxLength":300},{"name":"handoffNote","type":"textarea","required":false,"maxLength":1200}]}]}}$json$::jsonb $schema$;
create function dg_bo_private.fields(kind text,v jsonb,step integer,done boolean default false) returns jsonb language plpgsql set search_path='' as $$ declare schema jsonb:=dg_bo_private.schemas()->kind;s jsonb;f jsonb;known jsonb:='{}';k text;x jsonb;t text;ix integer:=0;required boolean;begin
 if jsonb_typeof(v) is distinct from 'object' or schema is null or step<0 or step>=jsonb_array_length(schema->'steps') then perform dg_bo_private.fail(422,'INVALID_WIZARD','Ongeldige wizardvelden of stap.');end if;
 perform dg_bo_private.assert_clean(v);
 for s in select * from jsonb_array_elements(schema->'steps') loop for f in select * from jsonb_array_elements(s->'fields') loop
 k:=f->>'name';known:=known||jsonb_build_object(k,true);x:=v->k;t:=coalesce(v->>k,'');required:=coalesce((f->>'required')::boolean,false) and (done or ix<step);
 if kind='wizard:deploy' and k in('productionHost','productionOrigin','productionProjectRef','productionSupabase') and v->>'scope'<>'production' then required:=false;end if;
 if required and btrim(t)='' then perform dg_bo_private.fail(422,'WIZARD_REQUIRED','Vul de vereiste wizardvelden in.',jsonb_build_object('fieldErrors',jsonb_build_object(k,'Verplicht veld')));end if;
 if x is not null then
 if f->>'type'='checkbox' then if jsonb_typeof(x)<>'boolean' then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Een controleveld moet een boolean zijn.');end if;
 else
 if jsonb_typeof(x)<>'string' or length(t)>coalesce((f->>'maxLength')::integer,1000) then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Een veld is te lang of ongeldig.');end if;
 if t<>'' then
 if f ? 'options' and not (f->'options')?t then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Kies een geldige veldoptie.');end if;
 if f ? 'pattern' and t !~ ('^('||(f->>'pattern')||')$') then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Een veld heeft een onjuist formaat.');end if;
 if f->>'type'='number' and (t !~ '^[0-9]+$' or length(t)>12) then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Gebruik een geldig geheel getal.');end if;
 if f->>'type'='number' and ((f ? 'min' and t::numeric<(f->>'min')::numeric) or (f ? 'max' and t::numeric>(f->>'max')::numeric)) then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Het getal valt buiten het bereik.');end if;
 if f->>'type'='email' and t !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Vul een volledig e-mailadres in.');end if;
 if f->>'type'='date' then if t !~ '^\d{4}-\d{2}-\d{2}$' then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Gebruik een geldige kalenderdatum.');end if;begin if to_char(t::date,'YYYY-MM-DD')<>t then raise exception 'date';end if;exception when others then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Gebruik een geldige kalenderdatum.');end;end if;
 if f->>'type'='url' and t !~ '^https://[^/@[:space:]]+(\/[^#[:space:]]*)?$' then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Gebruik HTTPS zonder inloggegevens of fragment.');end if;
 if k in('sender','replyTo','senderName','subject','displayName') and t ~ E'[\r\n]' then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Gebruik één regel.');end if;
 if k in('domain','hostname','publicHostname') and (length(t)>253 or t !~* '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$' or split_part(t,'.',-1) !~* '[a-z]') then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Gebruik een volledige hostnaam.');end if;
 if k in('templateText','subject') and regexp_replace(t,'\{\{[[:space:]]*(contact_name|invoice_number|portal_url)[[:space:]]*\}\}','','g') ~ '\{\{' then perform dg_bo_private.fail(422,'INVALID_WIZARD_FIELD','Onbekende templatevariabele.');end if;
 end if;end if;end if;
 end loop;ix:=ix+1;end loop;
 for k in select jsonb_object_keys(v) loop if not known?k and not(kind not like 'wizard:%' and k in('wizardStep','wizardCompleted','environment','mode')) then perform dg_bo_private.fail(422,'UNKNOWN_WIZARD_FIELD','Een wizardveld wordt niet herkend.',jsonb_build_object('fieldErrors',jsonb_build_object(k,'Onbekend veld')));end if;end loop;
 return v;
 end $$;
create function dg_bo_private.integration_values(kind text,v jsonb,environment text) returns jsonb language plpgsql set search_path='' as $$ declare step integer;completed boolean;begin
 if jsonb_typeof(v) is distinct from 'object' or coalesce(v->>'wizardStep','0') !~ '^\d{1,2}$' or coalesce(v->>'wizardCompleted','false') not in('true','false') then perform dg_bo_private.fail(422,'INVALID_INTEGRATION','Ongeldige installatiewizard.');end if;
 step:=coalesce((v->>'wizardStep')::integer,0);completed:=coalesce(v->>'wizardCompleted','false')='true';
 if dg_bo_private.schemas()?kind then
 if completed and step<>jsonb_array_length(dg_bo_private.schemas()->kind->'steps')-1 then perform dg_bo_private.fail(422,'INCOMPLETE_WIZARD','Doorloop eerst alle stappen.');end if;
 perform dg_bo_private.fields(kind,v,step,completed);
 else perform dg_bo_private.fail(422,'UNSUPPORTED_INTEGRATION','Deze installatiesoort heeft nog geen gecontroleerde databasevalidatie.');end if;
 return v||jsonb_build_object('environment',environment,'mode','metadata_only','wizardStep',step::text,'wizardCompleted',completed::text);end$$;
create function dg_bo_private.origin(t text) returns text language sql immutable set search_path='' as $$ select lower(rtrim(regexp_replace(t,':443/?$',''),'/')) $$;
create function dg_bo_private.runners(t text) returns text language sql immutable set search_path='' as $$ select string_agg(lower(btrim(x)),',' order by lower(btrim(x))) from unnest(string_to_array(t,','))x $$;
create function dg_bo_private.wizards(v jsonb,prior jsonb) returns jsonb language plpgsql set search_path='' as $$ declare r jsonb;old jsonb;vals jsonb;f jsonb;s jsonb;k text;out jsonb:='[]';ids text[]:='{}';ix integer;earliest integer;identity_changed boolean;begin
 if jsonb_typeof(v) is distinct from 'array' or jsonb_array_length(v)>40 then perform dg_bo_private.fail(422,'INVALID_WIZARDS','Bewaar maximaal 40 wizarddossiers.');end if;
 for r in select * from jsonb_array_elements(v) loop
 perform dg_bo_private.allowed(r,array['id','kind','step','values','updated','done','example','link']);
 if jsonb_typeof(r) is distinct from 'object' or jsonb_typeof(r->'id') is distinct from 'string' or jsonb_typeof(r->'kind') is distinct from 'string' or jsonb_typeof(r->'step') is distinct from 'number' or (r?'example' and jsonb_typeof(r->'example') is distinct from 'boolean') or (r->>'done'='true' and r->>'step'<>'7') then perform dg_bo_private.fail(422,'INVALID_WIZARD','Ongeldige wizardidentiteit of voortgang.');end if;
 if r->>'kind' not in('deploy','hardening') or coalesce(length(r->>'id'),0) not between 1 and 100 or r->>'id'=any(ids) or coalesce(r->>'step','') !~ '^[0-7]$' or (r?'done' and jsonb_typeof(r->'done')<>'boolean') then perform dg_bo_private.fail(422,'INVALID_WIZARD','Ongeldig of dubbel wizarddossier.');end if;
 ids:=array_append(ids,r->>'id');vals:=r->'values';perform dg_bo_private.fields('wizard:'||(r->>'kind'),vals,(r->>'step')::integer,coalesce((r->>'done')::boolean,false));
 select item into old from jsonb_array_elements(case when jsonb_typeof(prior)='array' then prior else '[]' end) item where item->>'id'=r->>'id' and item->>'kind'=r->>'kind';
 earliest:=100;identity_changed:=false;ix:=0;
 if old is not null then for s in select * from jsonb_array_elements(dg_bo_private.schemas()->('wizard:'||(r->>'kind'))->'steps') loop for f in select * from jsonb_array_elements(s->'fields') loop k:=f->>'name';if f->>'type'<>'checkbox' and old->'values'->k is distinct from vals->k then earliest:=least(earliest,ix);if k in('hostName','providerId','sourceSha','acceptedSha') then identity_changed:=true;end if;end if;end loop;ix:=ix+1;end loop;
 ix:=0;for s in select * from jsonb_array_elements(dg_bo_private.schemas()->('wizard:'||(r->>'kind'))->'steps') loop for f in select * from jsonb_array_elements(s->'fields') loop if f->>'type'='checkbox' and f->>'name'<>'registerInDg' and (ix>earliest or (ix=earliest and identity_changed)) then vals:=jsonb_set(vals,array[f->>'name'],'false');end if;end loop;ix:=ix+1;end loop;end if;
 if r->>'kind'='hardening' then
 if vals->>'tailAfterReloadVerified'='true' and (coalesce(vals->>'sshConfigVerified','false')<>'true' or coalesce(vals->>'tailLoginVerified','false')<>'true') then perform dg_bo_private.fail(422,'WIZARD_GUARD','Controleer eerst de SSH-instellingen en Tailscale-login.');end if;
 if vals->>'publicSshClosed'='true' then foreach k in array array['consoleVerified','inventoryVerified','hostKeyVerified','adminVerified','tailLoginVerified','tailPolicyVerified','sshConfigVerified','tailAfterReloadVerified','dualFirewallVerified'] loop if coalesce(vals->>k,'false')<>'true' then perform dg_bo_private.fail(422,'WIZARD_GUARD','Publieke SSH vereist alle herstel- en toegangscontroles.');end if;end loop;end if;
 else
 foreach k in array array['stagingOrigin','productionOrigin','stagingSupabase','productionSupabase'] loop if coalesce(vals->>k,'')<>'' and vals->>k !~ '^https://[^/@?#[:space:]]+/?$' then perform dg_bo_private.fail(422,'WIZARD_GUARD','Gebruik een HTTPS-origin zonder pad of inloggegevens.');end if;end loop;
 foreach k in array array['Origin','ProjectRef','Supabase','Config','Runner'] loop if coalesce(vals->>('staging'||k),'')<>'' and (case when k in('Origin','Supabase') then dg_bo_private.origin(vals->>('staging'||k)) when k='Runner' then dg_bo_private.runners(vals->>('staging'||k)) else lower(vals->>('staging'||k)) end)=(case when k in('Origin','Supabase') then dg_bo_private.origin(vals->>('production'||k)) when k='Runner' then dg_bo_private.runners(vals->>('production'||k)) else lower(vals->>('production'||k)) end) then perform dg_bo_private.fail(422,'WIZARD_GUARD','Staging en productie vereisen gescheiden doelen en configuratie.');end if;end loop;
 if lower(vals->>'stagingHost')=lower(vals->>'productionHost') and coalesce(vals->>'stagingPort','')<>'' and vals->>'stagingPort'=vals->>'productionPort' then perform dg_bo_private.fail(422,'WIZARD_GUARD','Een gedeelde host vereist verschillende loopbackpoorten.');end if;
 if coalesce(vals->>'callback','')<>'' and vals->>'callback' !~ '^/[^/][a-zA-Z0-9_./~-]*$' then perform dg_bo_private.fail(422,'WIZARD_GUARD','Gebruik een geldig app-callbackpad.');end if;
 if vals->>'ciGreen'='true' and (coalesce(vals->>'sourceSha','')='' or coalesce(vals->>'ciEvidence','')='') then perform dg_bo_private.fail(422,'WIZARD_GUARD','CI-bewijs en een volledige kandidaat-SHA zijn vereist.');end if;
 if vals->>'stagingHealthy'='true' and (coalesce(vals->>'sourceSha','')='' or lower(vals->>'sourceSha') is distinct from lower(vals->>'acceptedSha') or coalesce(vals->>'stagingConfig','')='' or coalesce(vals->>'acceptanceEvidence','')='') then perform dg_bo_private.fail(422,'WIZARD_GUARD','Gezonde staging vereist dezelfde SHA, configuratie en bewijs.');end if;
 if vals->>'stagingAccepted'='true' and (coalesce(vals->>'stagingHealthy','false')<>'true' or coalesce(vals->>'ciGreen','false')<>'true' or coalesce(vals->>'acceptedSha','')='' or lower(vals->>'sourceSha') is distinct from lower(vals->>'acceptedSha') or coalesce(vals->>'acceptanceEvidence','')='') then perform dg_bo_private.fail(422,'WIZARD_GUARD','Stagingacceptatie vereist actuele CI en gezond stagingbewijs.');end if;
 if vals->>'scope'='production' and vals->>'productionApproved'='true' and coalesce(vals->>'approvalEvidence','')='' or vals->>'restoreReady'='true' and coalesce(vals->>'restoreReference','')='' then perform dg_bo_private.fail(422,'WIZARD_GUARD','Vrijgave of herstelreferentie ontbreekt.');end if;
 end if;
 out:=out||jsonb_build_array(r||jsonb_build_object('values',vals));end loop;return out;end$$;
create function dg_bo_private.integration_dto(r public.dg_bo_integrations) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('id',r.id,'kind',r.kind,'name',r.name,'values',r.values,'revision',r.revision,'status',r.status,'environment',r.values->>'environment','updatedAt',r.updated_at,'createdAt',r.created_at,'lastTest',r.last_test,'testHistory',r.test_history,'lastSuccessfulTestAt',null,'providerWrites',false,'capabilities',jsonb_build_object('test',true,'preview',true,'activate',false,'pause',true),'mode','metadata_only')$$;
create function dg_bo_private.support_lookup(a jsonb,ticket text) returns public.dg_bo_support_tickets language plpgsql set search_path='' as $$declare r public.dg_bo_support_tickets;begin perform dg_bo_private.require_permission(a,'support.ticket.read');select * into r from public.dg_bo_support_tickets t where t.workspace_id=(a->>'workspaceId')::uuid and t.id=ticket and (a->>'role' in('admin','support') or t.organization_id::text=a->>'organizationId');if r.id is null then perform dg_bo_private.fail(404,'NOT_FOUND','Supportverzoek niet gevonden.');end if;return r;end$$;
create function dg_bo_private.support_dto(a jsonb,r public.dg_bo_support_tickets,summary boolean default false) returns jsonb language plpgsql stable set search_path='' as $$declare private boolean:=a->>'role' in('admin','support') and (a->'permissions')?'support.ticket.internal_note';thread jsonb;total bigint;begin
 select count(*) into total from public.dg_bo_support_messages m where m.workspace_id=r.workspace_id and m.ticket_id=r.id and (m.visibility='public' or private);
 select coalesce(jsonb_agg(item order by event_order),'[]') into thread from(select m.event_order,jsonb_build_object('id',m.id,'author',m.author,'body',m.body,'at',m.created_at,'type',m.type,'visibility',m.visibility,'attachments','[]'::jsonb) item from public.dg_bo_support_messages m where m.workspace_id=r.workspace_id and m.ticket_id=r.id and (m.visibility='public' or private) order by m.event_order desc limit case when summary then 1 else 1000 end) q;
 return jsonb_build_object('id',r.id,'organizationId',r.organization_id,'client',(select o.name from public.dg_bo_organizations o where o.id=r.organization_id and o.workspace_id=r.workspace_id),'service',r.service,'subject',r.subject,'category',r.category,'priority',r.priority,'status',r.status,'assignee',case when private then r.assignee else 'DG Support' end,'revision',case when private then r.revision else r.public_revision end,'createdAt',r.created_at,'updatedAt',case when private then r.updated_at else r.public_updated_at end,'messageCount',total,'messages',thread,'historyComplete',true,'historyLimit',case when private then 1000 else 500 end,'fixture',false,'mode','database_metadata','attachmentsEnabled',false,'emailEnabled',false);end$$;
create function dg_bo_private.text(v jsonb,k text,max_length integer,required boolean default true,single_line boolean default false) returns text language plpgsql set search_path='' as $$declare t text:=btrim(replace(v->>k,E'\r\n',E'\n'));begin if jsonb_typeof(v->k) is distinct from 'string' or (required and coalesce(t,'')='') or length(t)>max_length or t ~ '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]' or (single_line and t ~ E'[\r\n]') then perform dg_bo_private.fail(422,'INVALID_SUPPORT_FIELD','Een tekstveld is leeg, te lang of ongeldig.');end if;return t;end$$;
create function dg_bo_private.allowed(v jsonb,keys text[]) returns void language plpgsql set search_path='' as $$declare k text;begin for k in select jsonb_object_keys(v) loop if k='attachments' and v->k='[]' then continue;end if;if not k=any(keys) then perform dg_bo_private.fail(422,case when k='attachments' then 'ATTACHMENTS_DISABLED' else 'UNKNOWN_FIELD' end,'Een veld is niet toegestaan.');end if;end loop;end$$;
create function dg_bo_private.support_add(a jsonb,r public.dg_bo_support_tickets,body text,visibility text,type text default 'message') returns void language plpgsql set search_path='' as $$declare author text;begin
 if(select count(*) from public.dg_bo_support_messages m where m.workspace_id=r.workspace_id and m.ticket_id=r.id and m.visibility=support_add.visibility)>=500 then perform dg_bo_private.fail(409,'SUPPORT_THREAD_LIMIT','De maximale berichtgeschiedenis voor dit kanaal is bereikt.');end if;
 author:=case when visibility='internal' then 'DG Support' when a->>'role' in('admin','support') then 'Team DG Webservices' else (select o.name from public.dg_bo_organizations o where o.id=r.organization_id and o.workspace_id=r.workspace_id) end;
 insert into public.dg_bo_support_messages(workspace_id,ticket_id,visibility,author,body,type) values(r.workspace_id,r.id,visibility,author,body,type);end$$;
create function dg_bo_private.draft_target(a jsonb,k text) returns void language plpgsql set search_path='' as $$declare id text;begin perform dg_bo_private.require_permission(a,'support.draft.read');if k='create' then return;end if;if k !~ '^DG-[A-F0-9]{32}:(public|internal)$' then perform dg_bo_private.fail(422,'INVALID_DRAFT_KEY','Ongeldig supportconcept.');end if;id:=split_part(k,':',1);perform dg_bo_private.support_lookup(a,id);if split_part(k,':',2)='internal' then perform dg_bo_private.require_permission(a,'support.ticket.internal_note',true);end if;end$$;
create function dg_bo_private.draft_clear(a jsonb,k text,b jsonb) returns jsonb language plpgsql set search_path='' as $$ <<draft_clear>> declare d public.dg_bo_support_drafts;scope text:=jsonb_build_array(a->>'role',a->>'organizationId')::text;begin
 select * into d from public.dg_bo_support_drafts x where x.workspace_id=(a->>'workspaceId')::uuid and x.user_id=(a->>'id')::uuid and x.scope=draft_clear.scope and x.key=k;
 if b?'draftRevision' and (jsonb_typeof(b->'draftRevision')<>'number' or b->>'draftRevision' !~ '^\d+$' or (b->>'draftRevision')::bigint<>coalesce(d.revision,0)) then perform dg_bo_private.fail(409,'DRAFT_CONFLICT','Het supportconcept is gewijzigd.',jsonb_build_object('current',jsonb_build_object('key',k,'value',coalesce(d.value,'{}'),'revision',coalesce(d.revision,0))));end if;
 if d.key is null or coalesce(d.value->>'body','')<>btrim(replace(b->>'body',E'\r\n',E'\n')) then return null;end if;
 if not b?'draftRevision' and exists(select 1 from jsonb_each_text(d.value) q where btrim(replace(b->>q.key,E'\r\n',E'\n')) is distinct from q.value) then return null;end if;
 update public.dg_bo_support_drafts x set value='{}',revision=x.revision+1,updated_at=now() where x.workspace_id=d.workspace_id and x.user_id=d.user_id and x.scope=d.scope and x.key=d.key returning * into d;
 return jsonb_build_object('key',k,'value','{}'::jsonb,'revision',d.revision);end$$;
create function dg_bo_private.support(a jsonb,path text,method text,b jsonb,request_id text) returns jsonb language plpgsql set search_path='' as $$ <<support>> declare
 w uuid:=(a->>'workspaceId')::uuid;u uuid:=(a->>'id')::uuid;staff boolean:=a->>'role' in('admin','support');private boolean:=staff and (a->'permissions')?'support.ticket.internal_note';scope text:=jsonb_build_array(a->>'role',a->>'organizationId')::text;
 r public.dg_bo_support_tickets;org public.dg_bo_organizations;d public.dg_bo_support_drafts;items jsonb;counts jsonb;draft jsonb;v jsonb;k text;id text;message text;visibility text;status text;priority text;assignee text;public_change boolean;private_change boolean;cnt integer;
 categories constant jsonb:='["Technische vraag","Verhuizing","E-mail","Facturatie","Algemene vraag"]';services constant jsonb:='["Algemene vraag","Domeinen","E-mail","Facturatie"]';assignees constant jsonb:='["Nog niet toegewezen","DG Support","DG Techniek","DG Administratie"]';begin
 perform dg_bo_private.require_permission(a,'support.ticket.read');
 if path='/api/support/catalog' and method='GET' then
 select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'fixture',false,'services',services) order by o.name),'[]') into items from public.dg_bo_organizations o where o.workspace_id=w and (staff or o.id::text=a->>'organizationId');
 return jsonb_build_object('status',200,'value',jsonb_build_object('items',items,'assignees',case when staff then assignees else '[]' end,'categories',categories,'capabilities',jsonb_build_object('isStaff',staff,'canCreate',(a->'permissions')?'support.ticket.create','canReply',(a->'permissions')?'support.ticket.reply','canManage',staff and (a->'permissions')?'support.ticket.manage','canInternalNote',private,'canChangeStatus',(a->'permissions')?'support.ticket.status','attachments',false,'email',false,'mode','database_metadata')));end if;
 if path='/api/support/drafts' then perform dg_bo_private.require_permission(a,'support.draft.read');
 if method='GET' then items:='[]';for d in select * from public.dg_bo_support_drafts x where x.workspace_id=w and x.user_id=u and x.scope=support.scope order by x.key loop begin perform dg_bo_private.draft_target(a,d.key);items:=items||jsonb_build_array(jsonb_build_object('key',d.key,'value',d.value,'revision',d.revision));exception when sqlstate 'P0001' then null;end;end loop;return jsonb_build_object('status',200,'value',jsonb_build_object('items',items));end if;
 if method='PUT' then perform dg_bo_private.require_permission(a,'support.draft.write');perform dg_bo_private.allowed(b,array['key','value','revision']);k:=b->>'key';perform dg_bo_private.draft_target(a,k);v:=b->'value';if jsonb_typeof(v) is distinct from 'object' then perform dg_bo_private.fail(422,'INVALID_DRAFT','Een concept bevat tekstvelden.');end if;perform dg_bo_private.allowed(v,case when k='create' then array['organizationId','service','subject','category','priority','body'] else array['body'] end);
 for id in select jsonb_object_keys(v) loop perform dg_bo_private.text(v,id,case when id='body' then 8000 when id='subject' then 160 else 300 end,false,id<>'body');end loop;
 if coalesce(v->>'organizationId','')<>'' and not exists(select 1 from public.dg_bo_organizations o where o.workspace_id=w and o.id::text=v->>'organizationId' and (staff or o.id::text=a->>'organizationId')) then perform dg_bo_private.fail(404,'NOT_FOUND','Organisatie niet gevonden.');end if;
 select * into d from public.dg_bo_support_drafts x where x.workspace_id=w and x.user_id=u and x.scope=support.scope and x.key=k;
 if coalesce(b->>'revision','') !~ '^\d+$' or (b->>'revision')::numeric<>coalesce(d.revision,0) then perform dg_bo_private.fail(409,'REVISION_CONFLICT','Het concept is gewijzigd.',jsonb_build_object('current',jsonb_build_object('key',k,'value',coalesce(d.value,'{}'),'revision',coalesce(d.revision,0))));end if;
 insert into public.dg_bo_support_drafts(workspace_id,user_id,scope,key,value,revision) values(w,u,scope,k,v,coalesce(d.revision,0)+1) on conflict on constraint dg_bo_support_drafts_pkey do update set value=excluded.value,revision=excluded.revision,updated_at=now() returning * into d;
 perform dg_bo_private.audit(a,'support.draft.save',md5(k),'saved',request_id,jsonb_build_object('revision',d.revision));return jsonb_build_object('status',200,'value',jsonb_build_object('draft',jsonb_build_object('key',k,'value',v,'revision',d.revision)));end if;end if;
 if path='/api/support/tickets' and method='GET' then
 select coalesce(jsonb_agg(q.dto order by q.at desc,q.id),'[]') into items from(select t.id,case when private then t.updated_at else t.public_updated_at end at,dg_bo_private.support_dto(a,t,true) dto from public.dg_bo_support_tickets t where t.workspace_id=w and (staff or t.organization_id::text=a->>'organizationId') order by at desc,t.id limit 200)q;
 select jsonb_build_object('total',count(*),'active',count(*) filter(where t.status<>'resolved'),'waiting',count(*) filter(where t.status='waiting'),'resolved',count(*) filter(where t.status='resolved')) into counts from public.dg_bo_support_tickets t where t.workspace_id=w and (staff or t.organization_id::text=a->>'organizationId');
 return jsonb_build_object('status',200,'value',jsonb_build_object('items',items,'counters',counts,'limit',200,'hasMore',(counts->>'total')::bigint>200,'mode','database_metadata'));end if;
 if path='/api/support/tickets' and method='POST' then
 perform dg_bo_private.require_permission(a,'support.ticket.create');perform dg_bo_private.allowed(b,array['organizationId','service','subject','category','priority','body','draftRevision']);
 id:=coalesce(b->>'organizationId',a->>'organizationId');select * into org from public.dg_bo_organizations o where o.workspace_id=w and o.id::text=support.id and (staff or o.id::text=a->>'organizationId');if org.id is null then perform dg_bo_private.fail(404,'NOT_FOUND','Organisatie niet gevonden.');end if;
 message:=dg_bo_private.text(b,'body',8000);k:=dg_bo_private.text(b,'subject',160,true,true);if not services?coalesce(b->>'service','Algemene vraag') or not categories?coalesce(b->>'category','Algemene vraag') or coalesce(b->>'priority','normal') not in('normal','high','urgent') then perform dg_bo_private.fail(422,'INVALID_SUPPORT_FIELD','Kies een geldige dienst, categorie en prioriteit.');end if;
 draft:=dg_bo_private.draft_clear(a,'create',b);
 insert into public.dg_bo_support_tickets(workspace_id,organization_id,subject,service,category,priority,status) values(w,org.id,k,coalesce(b->>'service','Algemene vraag'),coalesce(b->>'category','Algemene vraag'),coalesce(b->>'priority','normal'),'new') returning * into r;
 perform dg_bo_private.support_add(a,r,message,'public');perform dg_bo_private.audit(a,'support.ticket.create',r.id,'created',request_id,jsonb_build_object('organizationId',org.id,'revision',1));return jsonb_build_object('status',201,'value',jsonb_strip_nulls(jsonb_build_object('ticket',dg_bo_private.support_dto(a,r),'clearedDraft',draft)));end if;
 if path ~ '^/api/support/tickets/DG-[A-F0-9]{32}(/messages)?$' then id:=split_part(path,'/',5);r:=dg_bo_private.support_lookup(a,id);
 if method='GET' and path not like '%/messages' then return jsonb_build_object('status',200,'value',jsonb_build_object('ticket',dg_bo_private.support_dto(a,r)));end if;
 if coalesce(b->>'revision','') !~ '^\d+$' or (b->>'revision')::numeric<>(case when private then r.revision else r.public_revision end) then perform dg_bo_private.fail(409,'REVISION_CONFLICT','Het supportverzoek is gewijzigd.',jsonb_build_object('current',dg_bo_private.support_dto(a,r)));end if;
 if method='POST' and path like '%/messages' then
 perform dg_bo_private.allowed(b,array['revision','body','visibility','draftRevision']);visibility:=coalesce(b->>'visibility','public');if visibility not in('public','internal') then perform dg_bo_private.fail(422,'INVALID_VISIBILITY','Kies een publieke reactie of interne notitie.');end if;perform dg_bo_private.require_permission(a,case when visibility='internal' then 'support.ticket.internal_note' else 'support.ticket.reply' end,visibility='internal');if r.status='resolved' then perform dg_bo_private.fail(409,'TICKET_RESOLVED','Heropen het verzoek voordat je reageert.');end if;
 message:=dg_bo_private.text(b,'body',8000);draft:=dg_bo_private.draft_clear(a,id||':'||visibility,b);perform dg_bo_private.support_add(a,r,message,visibility);status:=case when visibility='internal' then r.status when staff then 'waiting' else 'open' end;
 if status<>r.status then perform dg_bo_private.support_add(a,r,'Status gewijzigd naar '||case status when 'waiting' then 'wacht op klant' else 'in behandeling' end||'.','public','system');end if;
 update public.dg_bo_support_tickets t set status=support.status,revision=t.revision+1,public_revision=t.public_revision+case when visibility='public' then 1 else 0 end,updated_at=now(),public_updated_at=case when visibility='public' then now() else t.public_updated_at end where t.id=support.id and t.workspace_id=w returning * into r;
 perform dg_bo_private.audit(a,'support.ticket.'||case when visibility='internal' then 'internal_note' else 'reply' end,id,'saved',request_id,jsonb_build_object('visibility',visibility,'revision',r.revision));return jsonb_build_object('status',200,'value',jsonb_strip_nulls(jsonb_build_object('ticket',dg_bo_private.support_dto(a,r),'clearedDraft',draft)));end if;
 if method in('PATCH','PUT') and path not like '%/messages' then
 perform dg_bo_private.allowed(b,array['revision','assignee','priority','status']);if not (b ?| array['assignee','priority','status']) then perform dg_bo_private.fail(422,'SUPPORT_CHANGE_REQUIRED','Geef een wijziging op.');end if;
 if b ?| array['assignee','priority'] then perform dg_bo_private.require_permission(a,'support.ticket.manage',true);end if;if b?'assignee' then perform dg_bo_private.require_permission(a,'support.ticket.internal_note',true);end if;if b?'status' then perform dg_bo_private.require_permission(a,'support.ticket.status');end if;
 status:=coalesce(b->>'status',r.status);priority:=coalesce(b->>'priority',r.priority);assignee:=coalesce(b->>'assignee',r.assignee);
 if status not in('new','open','waiting','resolved') or priority not in('normal','high','urgent') or not assignees?assignee then perform dg_bo_private.fail(422,'INVALID_SUPPORT_FIELD','Ongeldige supportstatus of behandelaar.');end if;
 if not staff and status not in('open','resolved') then perform dg_bo_private.fail(403,'FORBIDDEN','Een klant kan alleen oplossen of heropenen.');end if;
 if status<>r.status and (r.status='resolved' and status<>'open' or r.status<>'resolved' and status not in('open','waiting','resolved')) then perform dg_bo_private.fail(422,'INVALID_SUPPORT_TRANSITION','Deze statusovergang is niet toegestaan.');end if;
 public_change:=status<>r.status or priority<>r.priority;private_change:=assignee<>r.assignee;
 if private_change then perform dg_bo_private.support_add(a,r,'Behandelaar gewijzigd naar '||assignee||'.','internal','system');end if;
 if priority<>r.priority then perform dg_bo_private.support_add(a,r,'Prioriteit gewijzigd naar '||priority||'.','public','system');end if;
 if status<>r.status then perform dg_bo_private.support_add(a,r,'Status gewijzigd naar '||status||'.','public','system');end if;
 if public_change or private_change then update public.dg_bo_support_tickets t set status=support.status,priority=support.priority,assignee=support.assignee,revision=t.revision+1,public_revision=t.public_revision+case when public_change then 1 else 0 end,updated_at=now(),public_updated_at=case when public_change then now() else t.public_updated_at end where t.id=support.id and t.workspace_id=w returning * into r;perform dg_bo_private.audit(a,'support.ticket.update',id,'saved',request_id,jsonb_build_object('revision',r.revision));end if;
 return jsonb_build_object('status',200,'value',jsonb_build_object('ticket',dg_bo_private.support_dto(a,r)));end if;end if;
 perform dg_bo_private.fail(404,'NOT_FOUND','Supportactie niet gevonden.');return null;end$$;
create function dg_bo_private.customer_registry(a jsonb) returns jsonb language plpgsql set search_path='' as $$declare w uuid:=(a->>'workspaceId')::uuid;items jsonb;receipts jsonb;rev bigint;begin
 perform dg_bo_private.require_permission(a,'customer.read',true);
 select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'billingEmail',o.billing_email,'country',o.country,'billingPaused',true,'status','imported_locally','serviceStatus','unlinked','revision',o.revision,'createdAt',o.created_at,'sources',(select coalesce(jsonb_agg(jsonb_build_object('sourceType',s.source_type,'customerReference',s.customer_reference)),'[]') from public.dg_bo_customer_sources s where s.workspace_id=w and s.organization_id=o.id)) order by o.created_at desc),'[]') into items from(select * from public.dg_bo_organizations where workspace_id=w order by created_at desc limit 500)o;
 select coalesce(jsonb_agg(r.receipt||jsonb_build_object('currentConfigurationMatch',r.receipt->>'integrationRevision'=i.revision::text and r.receipt->>'configurationDigest'=encode(sha256(convert_to(i.values::text,'UTF8')),'hex')) order by r.created_at desc),'[]') into receipts from(select * from public.dg_bo_import_receipts where workspace_id=w order by created_at desc limit 200)r left join public.dg_bo_integrations i on i.id::text=r.receipt->>'integrationId' and i.workspace_id=w;
 select count(*) into rev from public.dg_bo_import_receipts where workspace_id=w;
 return jsonb_build_object('status',200,'value',jsonb_build_object('items',items,'imports',receipts,'revision',rev,'limit',500,'mode','database_metadata'));end$$;
create function dg_bo_private.customer_import(a jsonb,r public.dg_bo_integrations,action text,b jsonb,request_id text) returns jsonb language plpgsql set search_path='' as $$declare
 w uuid:=(a->>'workspaceId')::uuid;u uuid:=(a->>'id')::uuid;v jsonb:=r.values;oldorg public.dg_bo_organizations;oldline public.dg_bo_import_receipts;stored public.dg_bo_import_plans;orgid uuid;planid uuid:=gen_random_uuid();receiptid uuid:=gen_random_uuid();registry_revision bigint;config_digest text:=encode(sha256(convert_to(v::text,'UTF8')),'hex');payload_digest text;row jsonb;plan jsonb;receipt jsonb;job jsonb;classification text;reason text;warnings jsonb:='["Facturatie blijft gepauzeerd; geen uitnodiging of factuur.","Dienst blijft ongekoppeld."]';begin
 perform dg_bo_private.require_permission(a,'integrations.read',true);perform dg_bo_private.require_permission(a,'customer.import.'||action,true);
 if r.kind<>'customers-import' then perform dg_bo_private.fail(422,'WRONG_IMPORT_KIND','Dit dossier is geen klantimport.');end if;
 if coalesce(b->>'revision','')!~'^\d+$' or (b->>'revision')::numeric<>r.revision then perform dg_bo_private.fail(409,'REVISION_CONFLICT','Het importdossier is gewijzigd.',jsonb_build_object('current',dg_bo_private.integration_dto(r)));end if;
 if v->>'wizardCompleted' is distinct from 'true' then perform dg_bo_private.fail(422,'IMPORT_DOSSIER_INCOMPLETE','Rond eerst het importdossier af.');end if;
 perform dg_bo_private.integration_values(r.kind,v,v->>'environment');select count(*) into registry_revision from public.dg_bo_import_receipts where workspace_id=w;
 if action='preview' then
 select o.* into oldorg from public.dg_bo_customer_sources s join public.dg_bo_organizations o on o.workspace_id=s.workspace_id and o.id=s.organization_id where s.workspace_id=w and s.source_type=v->>'sourceType' and s.customer_reference=v->>'customerReference';
 row:=jsonb_build_object('sourceType',v->>'sourceType','batchReference',v->>'batchReference','lineReference',v->>'customerReference','customerReference',v->>'customerReference','organizationName',v->>'organizationName','billingEmail',v->>'billingEmail','country',v->>'country','productVersion',v->>'productVersion','paidThrough',v->>'paidThrough','nextInvoiceDate',v->>'nextInvoiceDate','requestedResourceReference',v->>'resourceReference');payload_digest:=encode(sha256(convert_to(row::text,'UTF8')),'hex');
 select * into oldline from public.dg_bo_import_receipts x where x.workspace_id=w and x.source_type=v->>'sourceType' and x.batch_reference=v->>'batchReference' and x.line_reference=v->>'customerReference';
 classification:=case when oldorg.id is null then 'new' else 'existing' end;reason:=case when oldorg.id is null then 'Nieuwe organisatie via stabiele handmatige bronreferentie.' else 'Dezelfde stabiele bronreferentie bestaat al.' end;
 if oldline.id is not null and oldline.receipt->>'payloadDigest'<>payload_digest then classification:='conflict';reason:='Dezelfde bronbatch en regel bevatten afwijkende gegevens.';
 elsif oldorg.id is not null and (lower(btrim(oldorg.name))<>lower(btrim(v->>'organizationName')) or oldorg.billing_email<>v->>'billingEmail' or oldorg.country<>v->>'country') then classification:='conflict';reason:='De bronreferentie heeft afwijkende organisatiegegevens; handmatige beoordeling vereist.';
 elsif oldorg.id is null and exists(select 1 from public.dg_bo_organizations o where o.workspace_id=w and lower(btrim(o.name))=lower(btrim(v->>'organizationName'))) then classification:='conflict';reason:='Deze organisatienaam heeft een andere bronreferentie; geen automatische samenvoeging.';end if;
 if v->>'sourceType'<>'manual' or v->>'resourceReference'<>'unlinked' then classification:='conflict';reason:='Alleen handmatige metadata zonder providerbinding is voor deze database-import vrijgegeven.';end if;
 if (v->>'nextInvoiceDate')::date<=(v->>'paidThrough')::date then classification:='conflict';reason:='De volgende factuurdatum moet na de betaalde periode liggen.';end if;
 if (v->>'nextInvoiceDate')::date<current_date then warnings:=warnings||jsonb_build_array('Factuurdatum in het verleden; handmatige controle vereist, geen automatische nafacturatie.');end if;
 row:=row||jsonb_build_object('payloadDigest',payload_digest,'classification',classification,'reason',reason,'warnings',warnings,'billingPaused',true,'serviceStatus','unlinked','organizationId',oldorg.id);
 plan:=jsonb_build_object('id',planid,'integrationId',r.id,'integrationRevision',r.revision,'configurationDigest',config_digest,'registryRevision',registry_revision,'expiresAt',now()+interval '15 minutes','mode','database_metadata','status',case when classification='conflict' then 'blocked' else 'ready' end,'billingPaused',true,'noExternalWrites',true,'noInvitations',true,'rows',jsonb_build_array(row),'blockers',case when classification='conflict' then jsonb_build_array(reason) else '[]'::jsonb end,'createdAt',now());
 plan:=plan||jsonb_build_object('digest',encode(sha256(convert_to(plan::text,'UTF8')),'hex'));
 insert into public.dg_bo_import_plans(id,workspace_id,user_id,integration_id,integration_revision,configuration_digest,registry_revision,digest,plan,expires_at) values(planid,w,u,r.id,r.revision,config_digest,registry_revision,plan->>'digest',plan,now()+interval '15 minutes');
 perform dg_bo_private.audit(a,'customer.import.preview',planid::text,plan->>'status',request_id,jsonb_build_object('integrationId',r.id,'revision',r.revision));return jsonb_build_object('status',200,'value',jsonb_build_object('plan',plan));end if;
 if action='commit' then
 select * into stored from public.dg_bo_import_plans p where p.id::text=b->>'planId' and p.workspace_id=w and p.user_id=u and p.integration_id=r.id;if stored.id is null then perform dg_bo_private.fail(404,'NOT_FOUND','Importplan niet gevonden.');end if;plan:=stored.plan;
 if b->>'digest' is distinct from stored.digest or stored.digest<>encode(sha256(convert_to((plan-'digest')::text,'UTF8')),'hex') or stored.integration_revision<>r.revision or stored.configuration_digest<>config_digest then perform dg_bo_private.fail(409,'IMPORT_PLAN_CHANGED','De exacte preview of configuratie is gewijzigd.');end if;
 row:=plan->'rows'->0;select * into oldline from public.dg_bo_import_receipts x where x.workspace_id=w and x.source_type=row->>'sourceType' and x.batch_reference=row->>'batchReference' and x.line_reference=row->>'lineReference';
 if oldline.id is not null then if oldline.receipt->>'payloadDigest'<>row->>'payloadDigest' then perform dg_bo_private.fail(409,'IMPORT_LINE_CONFLICT','Deze bronregel heeft afwijkende gegevens.');end if;return jsonb_build_object('status',200,'value',jsonb_build_object('import',oldline.receipt,'plan',plan));end if;
 if stored.expires_at<=now() then perform dg_bo_private.fail(409,'IMPORT_PLAN_EXPIRED','De preview is verlopen.');end if;
 if plan->>'status'<>'ready' or stored.registry_revision<>registry_revision then perform dg_bo_private.fail(409,'IMPORT_PLAN_BLOCKED','De registratie is gewijzigd of de preview bevat conflicten.');end if;
 select s.organization_id into orgid from public.dg_bo_customer_sources s where s.workspace_id=w and s.source_type=row->>'sourceType' and s.customer_reference=row->>'customerReference';
 if orgid is null then insert into public.dg_bo_organizations(workspace_id,name,billing_email,country) values(w,row->>'organizationName',row->>'billingEmail',row->>'country') returning id into orgid;insert into public.dg_bo_customer_sources(workspace_id,source_type,customer_reference,organization_id,metadata) values(w,row->>'sourceType',row->>'customerReference',orgid,jsonb_build_object('billingPaused',true,'serviceStatus','unlinked'));end if;
 receipt:=jsonb_build_object('id',receiptid,'integrationId',r.id,'integrationRevision',r.revision,'configurationDigest',config_digest,'payloadDigest',row->>'payloadDigest','planId',stored.id,'status','imported_locally','mode','database_metadata','billingPaused',true,'noInvitations',true,'noExternalWrites',true,'organizationIds',jsonb_build_array(orgid),'sourceLineIds',jsonb_build_array(receiptid),'createdAt',now());
 insert into public.dg_bo_import_receipts(id,workspace_id,source_type,batch_reference,line_reference,configuration_digest,receipt) values(receiptid,w,row->>'sourceType',row->>'batchReference',row->>'lineReference',config_digest,receipt);
 insert into public.dg_bo_jobs as inserted_job(workspace_id,integration_id,kind,status,metadata) values(w,r.id,'customer.import','completed',jsonb_build_object('importId',receiptid,'billingPaused',true,'noExternalWrites',true,'noInvitations',true)) returning jsonb_build_object('id',inserted_job.id,'integrationId',inserted_job.integration_id,'action',inserted_job.kind,'status','completed_locally','mode','database_metadata','createdAt',inserted_job.created_at,'importId',receiptid,'billingPaused',true,'noExternalWrites',true,'noInvitations',true) into job;
 perform dg_bo_private.audit(a,'customer.import.commit',receiptid::text,'imported_locally',request_id,jsonb_build_object('planId',stored.id,'organizationId',orgid));return jsonb_build_object('status',200,'value',jsonb_build_object('import',receipt,'plan',plan,'job',job));end if;
 perform dg_bo_private.fail(404,'NOT_FOUND','Importactie niet gevonden.');return null;end$$;
create function dg_bo_private.inventory(v jsonb,prior jsonb,wizards jsonb) returns jsonb language plpgsql set search_path='' as $$declare slot text;item jsonb;dossier jsonb;old jsonb;inv jsonb:='{}';names text[]:='{}';providers text[]:='{}';name text;provider text;begin
 perform dg_bo_private.allowed(v,array['inventory','notes','acks','maintenance','audit','scenario']);
 if jsonb_typeof(v) is distinct from 'object' or jsonb_typeof(v->'inventory') is distinct from 'object' or (select count(*) from jsonb_object_keys(v->'inventory'))>1000 then perform dg_bo_private.fail(422,'INVALID_INVENTORY','Ongeldige metadata-inventaris.');end if;
 for slot,item in select * from jsonb_each(v->'inventory') loop
 if slot!~'^\d{1,4}$' or jsonb_typeof(item)<>'object' or item->>'example'='true' then perform dg_bo_private.fail(422,'EXAMPLE_INVENTORY_FORBIDDEN','Een voorbeelddossier kan geen echte host registreren.');end if;
 perform dg_bo_private.allowed(item,array['name','providerId','hostId','example','hardening','monitoring','provider','region','owner','environment','role','os','registeredAt','source','sourceRef','alias','reference','projects','note']);
 for name in select jsonb_object_keys(item) loop if name not in('hardening','example') and (jsonb_typeof(item->name)<>'string' or length(item->>name)>case when name='note' then 2000 when name='reference' then 500 else 300 end) then perform dg_bo_private.fail(422,'INVALID_INVENTORY','Inventarisvelden bevatten alleen begrensde metadata.');end if;end loop;
 name:=lower(rtrim(btrim(coalesce(item->>'name','')),'.'));provider:=btrim(coalesce(item->>'providerId',''));
 if name='' then inv:=inv||jsonb_build_object(slot,item);continue;end if;
 if length(name)>100 or length(provider)>200 or name=any(names) or (provider<>'' and provider=any(providers)) then perform dg_bo_private.fail(422,'HOST_IDENTITY_CONFLICT','De hostidentiteit is ongeldig of dubbel.');end if;names:=array_append(names,name);providers:=array_append(providers,provider);
 select x into old from jsonb_each(coalesce(prior->'inventory','{}')) q(k,x) where lower(rtrim(btrim(x->>'name'),'.'))=name or (provider<>'' and x->>'providerId'=provider) limit 1;
 if old is not null and (lower(rtrim(btrim(old->>'name'),'.'))<>name or coalesce(old->>'providerId','')<>provider) then perform dg_bo_private.fail(422,'HOST_IDENTITY_CONFLICT','De bestaande hostidentiteit wijkt af.');end if;
 if item?'hardening' then
 select r into dossier from jsonb_array_elements(case when jsonb_typeof(wizards)='array' then wizards else '[]' end)r where r->>'kind'='hardening' and r->>'done'='true' and coalesce(r->>'example','false')<>'true' and r->'values'->>'registerInDg'='true' and lower(rtrim(btrim(r->'values'->>'hostName'),'.'))=name and r->'values'->>'providerId'=provider;
 if dossier is null then perform dg_bo_private.fail(422,'HARDENING_DOSSIER_REQUIRED','Een passende, voltooide echte hardeningregistratie met opt-in is vereist.');end if;
 item:=item||jsonb_build_object('hardening',jsonb_build_object('dossierId',dossier->>'id','verification','reported_by_actor','verifiedExternally',false,'baseline','DG Ubuntu 24.04','status',case when exists(select 1 from jsonb_array_elements(dg_bo_private.schemas()->'wizard:hardening'->'steps')s cross join lateral jsonb_array_elements(s->'fields')f where f->>'type'='checkbox' and f->>'name'<>'registerInDg' and coalesce(dossier->'values'->>(f->>'name'),'false')<>'true') then 'reported_open' else 'reported_pass' end,'monitoring','pending','region',dossier->'values'->>'region','values',dossier->'values'));
 end if;
 item:=item||jsonb_build_object('hostId',coalesce(old->>'hostId',gen_random_uuid()::text),'example',false,'monitoring','pending','source','reported_by_actor');inv:=inv||jsonb_build_object(slot,item);
 end loop;return v||jsonb_build_object('inventory',inv);end$$;
create function dg_bo_private.state(a jsonb,path text,method text,b jsonb,request_id text) returns jsonb language plpgsql set search_path='' as $$ <<state>> declare w uuid:=(a->>'workspaceId')::uuid;u uuid:=(a->>'id')::uuid;scope text:=jsonb_build_array(a->>'role',a->>'organizationId')::text;key text;change jsonb;changes jsonb;result jsonb:='[]';current public.dg_bo_state;v jsonb;wizard_value jsonb;seen text[]:='{}';begin
 key:=substring(path from length('/api/state/')+1);
 if key='dg-midnight-support-v1' then perform dg_bo_private.fail(403,'STATE_UNAVAILABLE','Support gebruikt uitsluitend de geautoriseerde support-API.');end if;
 if method='GET' then perform dg_bo_private.require_permission(a,'state.read');
 if key not in('dg-midnight-services-v1','dg-midnight-management-v1','dg-midnight-account-v1','dg-midnight-commerce-v1','dg-midnight-infrastructure-v1','dg-midnight-vaults-v1','dg-midnight-maildesk-v1','dg-midnight-infra-wizards-v1') then perform dg_bo_private.fail(404,'NOT_FOUND','Gegevensonderdeel niet gevonden.');end if;
 if key in('dg-midnight-management-v1','dg-midnight-infrastructure-v1','dg-midnight-vaults-v1','dg-midnight-maildesk-v1','dg-midnight-infra-wizards-v1') and a->>'role'<>'admin' then perform dg_bo_private.fail(403,'FORBIDDEN','Beheerrecht vereist.');end if;
 select * into current from public.dg_bo_state s where s.workspace_id=w and s.user_id=u and s.scope=state.scope and s.key=state.key;return jsonb_build_object('status',200,'value',jsonb_build_object('value',current.value,'revision',coalesce(current.revision,0),'mode','database_metadata','simulated',false));end if;
 if method<>'PUT' then perform dg_bo_private.fail(405,'METHOD_NOT_ALLOWED','Deze methode is niet beschikbaar.');end if;
 perform dg_bo_private.require_permission(a,'state.write');if a->>'role'<>'admin' then perform dg_bo_private.fail(403,'FORBIDDEN','Beheerrecht vereist.');end if;
 changes:=case when path='/api/state' then b->'changes' else jsonb_build_array(b||jsonb_build_object('key',key)) end;
 if jsonb_typeof(changes) is distinct from 'array' or jsonb_array_length(changes) not between 1 and 8 then perform dg_bo_private.fail(422,'INVALID_BATCH','Bewaar één tot acht gegevensonderdelen.');end if;
 select s.value into wizard_value from public.dg_bo_state s where s.workspace_id=w and s.user_id=u and s.scope=state.scope and s.key='dg-midnight-infra-wizards-v1';
 for change in select * from jsonb_array_elements(changes) loop key:=change->>'key';
 if key=any(seen) then perform dg_bo_private.fail(422,'INVALID_BATCH','Een gegevensonderdeel komt dubbel voor.');end if;seen:=array_append(seen,key);
 if key not in('dg-midnight-infrastructure-v1','dg-midnight-infra-wizards-v1') then perform dg_bo_private.fail(409,'LEGACY_MUTATION_UNAVAILABLE','Deze oorspronkelijke demoactie heeft nog geen geautoriseerde productiebackend.');end if;
 select * into current from public.dg_bo_state s where s.workspace_id=w and s.user_id=u and s.scope=state.scope and s.key=state.key;
 if not change?'value' or coalesce(change->>'revision','')!~'^\d+$' or (change->>'revision')::numeric<>coalesce(current.revision,0) then perform dg_bo_private.fail(409,'REVISION_CONFLICT','De gegevens zijn gewijzigd.',jsonb_build_object('current',jsonb_build_object('key',key,'value',current.value,'revision',coalesce(current.revision,0))));end if;
 if key='dg-midnight-infra-wizards-v1' then wizard_value:=dg_bo_private.wizards(change->'value',current.value);end if;end loop;
 -- All revisions and wizard guards pass before any state writes; inventory uses the same batch's dossier.
 for change in select * from jsonb_array_elements(changes) loop key:=change->>'key';select * into current from public.dg_bo_state s where s.workspace_id=w and s.user_id=u and s.scope=state.scope and s.key=state.key;
 v:=case when key='dg-midnight-infra-wizards-v1' then wizard_value else dg_bo_private.inventory(change->'value',current.value,wizard_value) end;
 insert into public.dg_bo_state(workspace_id,user_id,scope,key,value,revision) values(w,u,scope,key,v,coalesce(current.revision,0)+1) on conflict on constraint dg_bo_state_pkey do update set value=excluded.value,revision=excluded.revision,updated_at=now() returning * into current;
 result:=result||jsonb_build_array(jsonb_build_object('key',key,'value',current.value,'revision',current.revision));perform dg_bo_private.audit(a,'state.metadata.save',key,'saved',request_id,jsonb_build_object('revision',current.revision,'payloadDigest',encode(sha256(convert_to(v::text,'UTF8')),'hex'),'atomicBatch',path='/api/state'));end loop;
 return jsonb_build_object('status',200,'value',case when path='/api/state' then jsonb_build_object('changes',result) else result->0 end);end$$;
create function dg_bo_private.dispatch(a jsonb,path text,method text,b jsonb,request_id text) returns jsonb language plpgsql set search_path='' as $$ <<dispatch>> declare
 w uuid:=(a->>'workspaceId')::uuid;r public.dg_bo_integrations;id text;action text;v jsonb;result jsonb;items jsonb;test jsonb;job jsonb;environment text;changed boolean;status integer:=200;begin
 if path='/api/state' or path like '/api/state/%' then return dg_bo_private.state(a,path,method,b,request_id);end if;
 if path like '/api/support/%' then return dg_bo_private.support(a,path,method,b,request_id);end if;
 if path='/api/customer-registry' and method='GET' then return dg_bo_private.customer_registry(a);end if;
 if path in('/api/jobs','/api/audit') and method='GET' then
 perform dg_bo_private.require_permission(a,case when path='/api/jobs' then 'jobs.read' else 'audit.read' end,true);
 if path='/api/jobs' then select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'integrationId',j.integration_id,'action',j.kind,'status',j.status,'createdAt',j.created_at,'mode','database_metadata')||j.metadata order by j.created_at desc),'[]') into items from(select * from public.dg_bo_jobs where workspace_id=w order by created_at desc limit 200)j;
 else select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'actorId',x.actor_id,'action',x.action,'targetId',x.resource_id,'outcome',x.outcome,'createdAt',x.created_at)||x.metadata order by x.created_at desc),'[]') into items from(select * from public.dg_bo_audit where workspace_id=w order by created_at desc limit 500)x;end if;return jsonb_build_object('status',200,'value',jsonb_build_object('items',items));end if;
 if path='/api/integrations' then
 perform dg_bo_private.require_permission(a,'integrations.read',true);
 if method='GET' then select coalesce(jsonb_agg(dg_bo_private.integration_dto(i) order by i.updated_at desc),'[]') into items from(select * from public.dg_bo_integrations where workspace_id=w order by updated_at desc limit 500)i;return jsonb_build_object('status',200,'value',jsonb_build_object('items',items,'limit',500));end if;
 if method='POST' then perform dg_bo_private.require_permission(a,'integrations.manage',true);perform dg_bo_private.allowed(b,array['kind','name','values']);
 select x.environment into environment from public.dg_bo_workspaces x where x.id=w;v:=dg_bo_private.integration_values(b->>'kind',b->'values',environment);
 insert into public.dg_bo_integrations(workspace_id,kind,name,values) values(w,b->>'kind',dg_bo_private.text(b,'name',120,true,true),v) returning * into r;perform dg_bo_private.audit(a,'integration.create',r.id::text,'draft',request_id,jsonb_build_object('kind',r.kind,'revision',r.revision));return jsonb_build_object('status',201,'value',jsonb_build_object('integration',dg_bo_private.integration_dto(r)));end if;end if;
 if path ~ '^/api/integrations/[a-f0-9-]{36}(/(test|preview|activate|pause|customer-import/(preview|commit)))?$' then
 perform dg_bo_private.require_permission(a,'integrations.read',true);id:=split_part(path,'/',4);select * into r from public.dg_bo_integrations i where i.id::text=dispatch.id and i.workspace_id=w;if r.id is null then perform dg_bo_private.fail(404,'NOT_FOUND','Installatiedossier niet gevonden.');end if;
 action:=split_part(path,'/',5);
 if action='customer-import' and method='POST' then return dg_bo_private.customer_import(a,r,split_part(path,'/',6),b,request_id);end if;
 if action='' and method='GET' then return jsonb_build_object('status',200,'value',jsonb_build_object('integration',dg_bo_private.integration_dto(r)));end if;
 if coalesce(b->>'revision','')!~'^\d+$' or (b->>'revision')::numeric<>r.revision then perform dg_bo_private.fail(409,'REVISION_CONFLICT','Het dossier is gewijzigd.',jsonb_build_object('current',dg_bo_private.integration_dto(r)));end if;
 if action='' and method='PUT' then
 perform dg_bo_private.require_permission(a,'integrations.manage',true);perform dg_bo_private.allowed(b,array['revision','name','values']);select x.environment into environment from public.dg_bo_workspaces x where x.id=w;v:=dg_bo_private.integration_values(r.kind,b->'values',environment);changed:=(r.values-array['wizardStep','wizardCompleted']) is distinct from (v-array['wizardStep','wizardCompleted']);
 update public.dg_bo_integrations i set values=v,name=case when b?'name' then dg_bo_private.text(b,'name',120,true,true) else i.name end,revision=i.revision+1,status=case when changed then 'draft' else i.status end,last_test=case when changed then null else i.last_test end,updated_at=now() where i.id=r.id returning * into r;
 perform dg_bo_private.audit(a,'integration.update',r.id::text,r.status,request_id,jsonb_build_object('kind',r.kind,'revision',r.revision));return jsonb_build_object('status',200,'value',jsonb_build_object('integration',dg_bo_private.integration_dto(r)));end if;
 if method='POST' and action in('test','preview','activate','pause') then
 perform dg_bo_private.require_permission(a,'integrations.'||action,true);perform dg_bo_private.allowed(b,array['revision']);
 if action='preview' then return jsonb_build_object('status',200,'value',jsonb_build_object('integration',dg_bo_private.integration_dto(r),'plan',jsonb_build_object('id',gen_random_uuid(),'integrationId',r.id,'revision',r.revision,'mode','metadata_only','status','blocked','changes','[]'::jsonb,'noExternalWrites',true,'blockers',jsonb_build_array('Provideraccount, credentials, resourcescope en afzonderlijke uitvoering zijn niet geverifieerd.'))));end if;
 if action='test' then test:=jsonb_build_object('id',gen_random_uuid(),'revision',r.revision,'testedRevision',r.revision,'createdAt',now(),'status','blocked','simulated',true,'providerWrites',false,'summary','Alleen metadata gevalideerd; geen externe verbinding of accountcontrole.');end if;
 update public.dg_bo_integrations i set revision=i.revision+1,status=case when action='pause' then 'paused' else 'blocked' end,last_test=case when action='test' then test else i.last_test end,test_history=case when action='test' then (select coalesce(jsonb_agg(t.val order by t.ord),'[]') from jsonb_array_elements(i.test_history||jsonb_build_array(test)) with ordinality t(val,ord) where t.ord>jsonb_array_length(i.test_history)+1-20) else i.test_history end,updated_at=now() where i.id=r.id returning * into r;
 insert into public.dg_bo_jobs as inserted_job(workspace_id,integration_id,kind,status,metadata) values(w,r.id,action,'blocked',jsonb_build_object('simulated',true,'providerWrites',false,'summary','Provideruitvoering is geblokkeerd.')) returning jsonb_build_object('id',inserted_job.id,'integrationId',inserted_job.integration_id,'action',inserted_job.kind,'status',inserted_job.status,'createdAt',inserted_job.created_at,'simulated',true,'providerWrites',false) into job;
 perform dg_bo_private.audit(a,'integration.'||action,r.id::text,r.status,request_id,jsonb_build_object('kind',r.kind,'revision',r.revision,'simulated',true));result:=jsonb_build_object('integration',dg_bo_private.integration_dto(r),'job',job);
 if action='activate' then result:=result||jsonb_build_object('code','ACTIVATION_BLOCKED','message','Activering vereist een afzonderlijk vrijgegeven provideraccount, echte verificatie en uitvoeradapter.');status:=409;end if;
 return jsonb_build_object('status',status,'value',result);end if;end if;
 perform dg_bo_private.fail(404,'NOT_FOUND','API-route niet gevonden.');return null;end$$;
create function public.dg_bo_domain(p_path text,p_method text default 'GET',p_body jsonb default '{}',p_idempotency_key text default null,p_request_id text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare a jsonb;result jsonb;fingerprint text;old public.dg_bo_idempotency;begin
 a:=dg_bo_private.context();
 if p_request_id is not null and p_request_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then perform dg_bo_private.fail(422,'INVALID_REQUEST_ID','Ongeldige aanvraagreferentie.');end if;
 perform dg_bo_private.assert_clean(to_jsonb(p_request_id));
 if p_path is null or length(p_path)>300 or p_path !~ '^/api/[A-Za-z0-9/_-]+$' or coalesce(p_method,'') not in('GET','POST','PUT','PATCH') or jsonb_typeof(p_body) is distinct from 'object' then perform dg_bo_private.fail(422,'INVALID_REQUEST','Ongeldige API-aanvraag.');end if;
 if p_method<>'GET' then
 perform dg_bo_private.assert_clean(p_body);
 -- One transaction lock per workspace makes CAS, batch changes and import plans atomic.
 perform pg_advisory_xact_lock(hashtextextended('dg_bo:'||(a->>'workspaceId'),0));
 end if;
 if p_method='POST' then
 perform dg_bo_private.assert_clean(to_jsonb(p_idempotency_key));
 if p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_.:-]{8,128}$' then perform dg_bo_private.fail(422,'IDEMPOTENCY_REQUIRED','Gebruik een unieke Idempotency-Key van 8 tot 128 tekens.');end if;
 -- Current authorization visibility participates; revoked internal access never replays private DTOs.
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('path',p_path,'method',p_method,'body',p_body,'actor',a)::text,'UTF8')),'hex');
 select * into old from public.dg_bo_idempotency x where x.workspace_id=(a->>'workspaceId')::uuid and x.user_id=(a->>'id')::uuid and x.key=p_idempotency_key;
 if old.key is not null then if old.fingerprint<>fingerprint then perform dg_bo_private.fail(409,'IDEMPOTENCY_CONFLICT','Deze aanvraagcode hoort bij andere gegevens of bevoegdheden.');end if;return old.response;end if;
 end if;
 result:=dg_bo_private.dispatch(a,p_path,p_method,p_body,p_request_id);
 if p_method='POST' then insert into public.dg_bo_idempotency(workspace_id,user_id,key,fingerprint,response) values((a->>'workspaceId')::uuid,(a->>'id')::uuid,p_idempotency_key,fingerprint,result);end if;return result;
 exception when sqlstate 'P0001' then
 begin result:=sqlerrm::jsonb;if jsonb_typeof(result)='object' and result?'status' and result?'value' then return result;end if;exception when others then null;end;return jsonb_build_object('status',500,'value',jsonb_build_object('code','INTERNAL_ERROR','message','De aanvraag kon niet veilig worden verwerkt.'));
 when others then return jsonb_build_object('status',500,'value',jsonb_build_object('code','INTERNAL_ERROR','message','De aanvraag kon niet veilig worden verwerkt.'));
 end$$;
revoke all on function public.dg_bo_domain(text,text,jsonb,text,text) from public,anon;grant execute on function public.dg_bo_domain(text,text,jsonb,text,text) to authenticated;
-- Helpers cannot be invoked directly through PostgREST, including its authenticated role.
revoke all on all functions in schema dg_bo_private from public,anon,authenticated;
comment on function public.dg_bo_context() is 'Current non-anonymous Auth user, MFA aal2, extant session and explicit active database membership; no automatic owner enrollment.';
comment on function public.dg_bo_domain(text,text,jsonb,text,text) is 'Scoped metadata only. All provider writes, billing, email, attachments and live resource activation remain blocked.';
commit;
